class V2Pagination(TypedDict):
  """Cursor pagination metadata accompanying a Coinbase App v2 list response. The real shape varies noticeably by endpoint (verified live): some list endpoints echo `next_starting_after`/`previous_ending_before` cursor values or a `total_count`, others use a bare `page` index instead of URI-based paging, and `limit`/`previous_uri`/`next_uri` are not reliably present on every endpoint — so only the fields common to every observed v2 list response stay required."""

  ending_before: str | None
  """Cursor: resource id marking the end of the previous page, or null when none was used."""
  starting_after: str | None
  """Cursor: resource id marking the start of the next page, or null when none was used."""
  limit: NotRequired[int]
  """Number of results returned per call. Accepted values: 0-100, default 25."""
  order: Literal['desc', 'asc']
  """Result order: `desc` (default, newest first) or `asc`."""
  previous_uri: NotRequired[str | None]
  """Relative URI for the previous page of results, or null when there is no previous page."""
  next_uri: NotRequired[str | None]
  """Relative URI for the next page of results, or null when there is no next page. The API embeds the cursor for the next call into this URI rather than publishing it as a bare value."""
  next_starting_after: NotRequired[str | None]
  """Cursor for the next page, duplicating `next_uri`'s query param — present on some v2 list endpoints. Verified live."""
  previous_ending_before: NotRequired[str | None]
  """Cursor for the previous page, duplicating `previous_uri`'s query param — present on some v2 list endpoints. Verified live."""
  total_count: NotRequired[int]
  """Total number of results across all pages, as an integer string — present on some v2 list endpoints (e.g. deposits, withdrawals) instead of `next_starting_after`/`previous_ending_before`. Verified live."""
  page: NotRequired[int]
  """Zero-based page index — present on some v2 list endpoints (e.g. addresses) instead of `next_uri`/`previous_uri`. Verified live."""


