class V2Transfer(TypedDict):
  """A v2 fiat transfer (deposit or withdrawal) as returned by the create/commit calls. Undocumented in prose -- typed from the raw response examples on the Fiat Deposits/Fiat Withdrawals pages, which show a different shape than the `Deposit`/`Withdrawal` resource described in those same pages' overview and returned by the list/show calls."""

  user_entered_amount: TransferMoney
  """Amount as entered by the caller, before fees."""
  amount: TransferMoney
  """Transfer amount."""
  total: TransferMoney
  """Total amount including fees."""
  subtotal: TransferMoney
  """Amount without fees."""
  idem: str
  """Idempotency key for this transfer."""
  committed: bool
  """Whether this transfer has been committed."""
  id: str
  """Transfer id."""
  instant: bool
  """Whether this transfer executes instantly."""
  source: TransferParty
  """Where the funds move from."""
  target: TransferParty
  """Where the funds move to."""
  payout_at: TimestampIso | None
  """When the transfer is expected to pay out, RFC3339, or null when not yet scheduled."""
  status: str
  """Transfer status. Empty string was observed for a freshly created, uncommitted transfer; the full set of values is undocumented."""
  user_reference: str
  """Human-facing reference code for this transfer; empty string when unset."""
  type: str
  """Transfer type, e.g. `TRANSFER_TYPE_DEPOSIT` or `TRANSFER_TYPE_WITHDRAWAL`."""
  created_at: TimestampIso | None
  """When this transfer was created, RFC3339, or null. Observed null on a freshly created transfer."""
  updated_at: TimestampIso | None
  """When this transfer was last updated, RFC3339, or null. Observed null on a freshly created transfer."""
  user_warnings: list[Any]
  """Warnings surfaced to the user about this transfer. Empty in every captured example; item shape unconfirmed."""
  fees: list[TransferFee]
  """Fee line items charged against this transfer. Empty in every captured example."""
  total_fee: TransferFee
  """Total fee summary for this transfer."""
  cancellation_reason: str | None
  """Reason this transfer was cancelled, or null when it was not cancelled."""
  hold_days: int
  """Number of days funds are held before this transfer completes."""
  nextStep: str | None
  """Next action required to progress this transfer, or null when none is required. Naming (camelCase amid an otherwise snake_case object) is as observed on the wire."""
  checkout_url: str
  """URL to complete this transfer in a browser, when applicable; empty string otherwise."""
  requires_completion_step: bool
  """Whether this transfer requires an additional completion step (e.g. a `commit` call)."""
